import hashlib
import importlib.util
import os
import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

TOOLS = Path(__file__).resolve().parents[1]
SPEC = importlib.util.spec_from_file_location("check_gen", TOOLS / "check_gen.py")
cg = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(cg)

def read(p):
    with open(p, encoding="utf-8") as f:
        return f.read()


def write(p, s, mode="w"):
    with open(p, mode, **({} if "b" in mode else {"encoding": "utf-8"})) as f:
        f.write(s)


KERNEL_IMAGE = """\
-- AUTO-GENERATED by tools/dump_kernel.py from kernel (xv6-riscv abc1234); do not edit.
namespace Xv6.Kernel
def textChunk0 : List KInstr := [
  -- nop
  ⟨0x80000000, 2, 0x0001⟩,
  -- ret
  ⟨0x80000002, 2, 0x8082⟩
]
end Xv6.Kernel
"""


class RawImageTests(unittest.TestCase):
    def test_elf_raw_round_trip(self):
        data = bytes(range(70))                       # 3 rows, the last one padded
        rows = [int.from_bytes(data[i:i + 32].ljust(32, b"\0"), "big") for i in range(0, 70, 32)]
        src = ("def elfSize : Nat := 70\n\n"
               "@[irreducible] def elfPage0 : List Nat := [\n"
               + ",\n".join("  " + ("0" if r == 0 else "0x%064x" % r) for r in rows[:2]) + "\n]\n\n"
               "@[irreducible] def elfPage1 : List Nat := [\n  0x%064x\n]\n" % rows[2])
        self.assertEqual(cg.elf_raw_bytes(src), data)

    def test_elf_raw_rejects_a_size_that_does_not_fit(self):
        src = "def elfSize : Nat := 99\n\n@[irreducible] def elfPage0 : List Nat := [\n  0x01\n]\n"
        with self.assertRaises(ValueError):
            cg.elf_raw_bytes(src)

    def test_fs_img_round_trip_through_the_dumper(self):
        img = bytes([7]) * 1024 + bytes(1024) + bytes(range(256)) * 4
        with tempfile.TemporaryDirectory() as d:
            p = os.path.join(d, "fs.img")
            write(p, img, "wb")
            out = os.path.join(d, "FsImgRaw.lean")
            subprocess.run([sys.executable, str(TOOLS / "dump_fs_image.py"), "--img", p,
                            "--rev", "abc1234", "--out", out], check=True, capture_output=True)
            src = read(out)
            self.assertEqual(cg.fs_img_bytes(src), img)
            gen, source, rev, md5 = cg.header(out)
            self.assertEqual((gen, rev, md5), ("tools/dump_fs_image.py", "abc1234",
                                               hashlib.md5(img).hexdigest()))

    def test_header_with_and_without_md5(self):
        with tempfile.TemporaryDirectory() as d:
            p = os.path.join(d, "K.lean")
            write(p, KERNEL_IMAGE)
            self.assertEqual(cg.header(p), ("tools/dump_kernel.py", "kernel", "abc1234", None))
            write(p, "import X\n")
            with self.assertRaises(ValueError):
                cg.header(p)


class RegenTests(unittest.TestCase):
    """The regenerate-and-diff loop on a miniature tree, with the real
    generator (tools/gen_text_tree.py)."""

    def setUp(self):
        self.d = tempfile.TemporaryDirectory()
        self.repo = os.path.join(self.d.name, "repo")
        os.makedirs(os.path.join(self.repo, "Xv6"))
        os.makedirs(os.path.join(self.repo, "tools"))
        shutil.copy(TOOLS / "gen_text_tree.py", os.path.join(self.repo, "tools"))
        write(os.path.join(self.repo, "Xv6", "KernelImage.lean"), KERNEL_IMAGE)
        subprocess.run([sys.executable, "tools/gen_text_tree.py", "--image", "Xv6/KernelImage.lean",
                        "--out", "Xv6/KernelTree.lean"], cwd=self.repo, check=True, capture_output=True)

    def tearDown(self):
        self.d.cleanup()

    def run_check(self):
        work = os.path.join(self.d.name, "work")
        os.makedirs(work, exist_ok=True)
        c = cg.Ctx(self.repo, work, "no-such-objdump", None, False)
        return cg.run_checks(c, only=["kernel-tree"])

    def test_an_untouched_tree_passes(self):
        c = self.run_check()
        self.assertEqual([(n, s) for n, s, _ in c.results], [("kernel-tree", cg.OK)])

    def test_a_hand_edit_of_the_generated_file_fails_with_a_diff(self):
        p = os.path.join(self.repo, "Xv6", "KernelTree.lean")
        s = read(p).replace("0x8082", "0x8083")
        write(p, s)
        c = self.run_check()
        self.assertEqual(c.results[0][1], cg.FAIL)
        self.assertIn("0x8083", c.diffs[0][1])

    def test_a_moved_input_fails(self):
        p = os.path.join(self.repo, "Xv6", "KernelImage.lean")
        s = read(p).replace("0x0001", "0x0013")
        write(p, s)
        self.assertEqual(self.run_check().results[0][1], cg.FAIL)

    def test_a_crashing_generator_is_a_failure_not_a_skip(self):
        write(os.path.join(self.repo, "Xv6", "KernelImage.lean"), "-- nothing\n")
        c = self.run_check()
        self.assertEqual(c.results[0][1], cg.FAIL)
        self.assertIn("gen_text_tree.py failed", c.results[0][2])

    def test_the_tree_is_never_modified(self):
        p = os.path.join(self.repo, "Xv6", "KernelTree.lean")
        s = read(p).replace("0x8082", "0x8083")
        write(p, s)
        self.run_check()
        self.assertEqual(read(p), s)


class RenderTests(unittest.TestCase):
    def test_exit_status_follows_failures_only(self):
        c = cg.Ctx("/r", "/w", "no-such-objdump", None, False)
        c.record("a", cg.OK, "fine")
        c.record("b", cg.SKIP, "no objdump")
        self.assertIn("1 ok, 0 failed, 1 skipped", cg.render(c, "text"))
        self.assertIn("| `b` | skipped |", cg.render(c, "md"))


if __name__ == "__main__":
    unittest.main()
